{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, the closest retinoid acid analogue, has a systemic bioavailability of 40% at 1 mg/kg/day, which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a retinoid acid, has an absolute oral bioavailability of approximately 60% (range 36–95%) after a single 50-mg oral dose, supporting that retinoid structures can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a neutral lipophilic retinoid ester, has an absolute oral bioavailability of about 40%, indicating that neutral retinoid derivatives are well absorbed enough to exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "13-cis-Retinoic acid was reported to have low absolute bioavailability with significant gut degradation, but this applies to the ionizable carboxylic acid form rather than the neutral amide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a neutral retinoid amide (4-hydroxyphenylretinamide). Direct retinoid acid evidence is mixed, but the more relevant neutral retinoid derivatives—etretinate (~40%) and acitretin (~60%)—consistently exceed the 20% threshold. The amide modification removes the ionizable carboxylic acid and is expected to maintain or improve absorption relative to the acid. The single low-bioavailability record for 13-cis-retinoic acid is outweighed by the broader retinoid derivative evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query amide (N-(4-hydroxyphenyl)retinamide).",
    "The effect of the 4-hydroxyphenylamide moiety on the absorption of a large lipophilic retinoid chain is not directly evidenced.",
    "Food effect and formulation dependence for the query are unknown."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C46"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "retinoic acid analogues"
    },
    {
      "applicability": "high",
      "card_ids": ["C08"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "retinoid acids"
    },
    {
      "applicability": "high",
      "card_ids": ["C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "retinoid esters/neutral derivatives"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C14"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "retinoic acid analogues"
    }
  ],
  "revision_action": "initial"
}

